CREATE OR REPLACE FUNCTION gx_l1(n NUMBER) RETURN NUMBER IS
BEGIN
  RETURN TRUNC(n / 3);
END;
/
CREATE OR REPLACE FUNCTION gx_l2(n NUMBER) RETURN NUMBER IS
BEGIN
  RETURN TRUNC(n, 2);
END;
/
CREATE OR REPLACE FUNCTION gx_l3(n NUMBER) RETURN NUMBER IS
  f FLOAT(10) := n;
BEGIN
  RETURN f * 2;
END;
/
CREATE OR REPLACE FUNCTION gx_l4(n NUMBER) RETURN NUMBER IS
  s SIMPLE_INTEGER := 1;
  k NATURAL := 2;
  p POSITIVE := 3;
  g SIGNTYPE := -1;
BEGIN
  RETURN s + k + p + g + n;
END;
/
CREATE OR REPLACE FUNCTION gx_l5(p VARCHAR2) RETURN NUMBER IS
BEGIN
  RETURN INSTR(p, '.', -1) * 10 + INSTR(p, '.', 1, 2);
END;
/
CREATE OR REPLACE FUNCTION gx_l6(d1 DATE, d2 DATE) RETURN NUMBER IS
  days NUMBER;
BEGIN
  days := d1 - d2;
  RETURN days;
END;
/
CREATE OR REPLACE FUNCTION gx_l7(d DATE) RETURN VARCHAR2 IS
  nxt DATE := d + 1;
BEGIN
  RETURN TO_CHAR(nxt, 'YYYY-MM-DD') || '|' || TO_CHAR(TRUNC(d) - 7, 'YYYY-MM-DD');
END;
/
